use std :: path :: Path ; use crate :: Match ; use crate :: utils :: format_match ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Truncates search output based on line limit, using search directory for"] # [doc = " relative paths"] pub fn truncate_search_output (output : & [Match] , start_line : usize , max_lines : usize , max_bytes : usize , search_dir : & Path ,) -> TruncatedSearchOutput { let output = output . iter () . map (| v | format_match (v , search_dir)) . collect :: < Vec < _ > > () ; TruncatedSearchOutput :: from (output) . truncate_by_lines (start_line , max_lines) . truncate_by_bytes (max_bytes) }